package android.widget;import android.content.Context;import android.content.res.ColorStateList;public class TextView extends android.view.View {private int color=0xffdedede;private CharSequence text="abc";public TextView(Context c){super(c);}public int getCurrentTextColor(){return color;}public void setTextColor(int c){color=c;}public ColorStateList getTextColors(){return ColorStateList.valueOf(color);}public void setText(CharSequence value){text=value;}public CharSequence getText(){return text;} }
